-- Migration 037: Products under Logs, kept separately for Production and the Nursery.
-- Nursery products come from the Fert List in WebbNursery_2026.xlsx, informed by the 2026 Spray Log (which is imported
-- too, as Nursery spray/feed logs). Production keeps the Farm Data products it actually uses.
-- Generated by tools/import_nursery_logs.py. Run after 032 (and 033). Safe to re-run.
set client_min_messages = warning;

alter table input_products add column if not exists module text;
alter table input_products add column if not exists form text;          -- type / form (liquid, WDG, granules…)
alter table input_products add column if not exists nutrients text;     -- secondary + micronutrients
alter table input_products add column if not exists label_url text;     -- label / SDS link
alter table input_products add column if not exists updated_at timestamptz not null default now();
update input_products set module = 'cultivation' where module is null;
alter table input_products alter column module set default 'cultivation';
alter table input_products alter column module set not null;
alter table input_products drop constraint if exists input_products_name_key;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'input_products_module_name_key') then
    alter table input_products add constraint input_products_module_name_key unique (module, name);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'input_products_module_check') then
    alter table input_products add constraint input_products_module_check check (module in ('cultivation','nursery'));
  end if;
end $$;

-- Production: keep the products it uses (Farm Data list, its logs and recipes, anything priced); the nursery-only ones move out
delete from input_products p where p.module = 'cultivation' and p.price is null
   and p.name not in ('True Organics (8-0-0)','True Organics (14-0-0)','True Organics (16-0-0)','Agrothrive LFP (2-7-0)','Agrothrive LF (2.5-2.5-2.5)',
     'Diamond K SOP (0-0-50)','Biomin Copper','Biomin Zinc','Regalia','Maritime Kelp','Biolink Molybdenum','Rebound Cobalt','DiPel DF','Microthiol Disperss',
     'ThermX70','CFO','Spectrum PSB','Bio-Tam 2.0','Nature Safe 7-12-0','True Organics 13-0-0','Worm Compost','Gypsum','Biomin Iron','Biomin Manganese','Biomin Calcium','Humic 600')
   and not exists (select 1 from ops_logs l, jsonb_array_elements(l.products) x where l.module = 'cultivation' and lower(x ->> 'product') = lower(p.name))
   and not exists (select 1 from ops_recipes r, jsonb_array_elements(r.products) x where r.module = 'cultivation' and lower(x ->> 'product') = lower(p.name));
-- Production's Regalia is the field one (per acre), not the nursery's mL per gallon
update input_products set manufacturer = 'Marrone Biosciences', rate = 32, rate_unit = 'fl oz/acre', price = coalesce(price, 1.86), price_unit = coalesce(price_unit, 'fl oz'),
       pesticide = true, kind = 'Biofungicide', full_name = 'Regalia Biofungicide'
 where module = 'cultivation' and name = 'Regalia' and (rate_unit is null or rate_unit ilike '%/gal');
-- per-gallon rates on Production products came from the nursery list: clear them so the logged per-acre rate fills in below
update input_products set rate = null, rate_unit = null where module = 'cultivation' and rate_unit ilike '%/gal';
